  descendRawSourceFragments(block) {
    const variadic = Object.keys(block.inputs).filter(name => /^ARG\d+$/.test(name)).sort((a, b) => Number(a.substring(3)) - Number(b.substring(3)));
    return (variadic.length ? variadic : ['A', 'B', 'C']).filter(name => block.inputs[name]).map(name => this.descendInputOfBlock(block, name, true));
  }

